SLOT = {m: i for i, m in enumerate(("Outfit", "Skin", "Leather", "Cloth"))}
for p in body.data.polygons:
    c = p.center
    p.use_smooth = True
    ax = abs(c.x)
    if c.z > 1.44 and ax < 0.075:
        slot = "Skin"                     # neck
    elif c.z > 1.30 and ax > 0.17:        # arms (T-pose)
        slot = "Outfit" if ax < 0.43 else ("Skin" if ax < 0.54 else "Leather")  # sleeve, forearm, bracer + glove
    elif c.z > 0.97:
        slot = "Outfit"                   # tunic
    elif c.z > 0.31:
        slot = "Cloth"                    # trousers
    else:
        slot = "Leather"                  # boots
    p.material_index = SLOT[slot]

# ---------------------------------------------------------------- head, face, hair

HEAD_C = Vector((0, 0.004, 1.668))


def head_shape(x, y, z):
    # A rounder skull on top, a narrower jaw and a slightly forward chin below.
    if z < 0:
        k = 1.0 - 0.28 * (-z)
        x *= k
        y = y * (1.0 - 0.12 * (-z)) - 0.10 * (-z) * (1 if y < 0 else 0)
    return x, y, z


parts = []  # (object, bone)
