# ---------------------------------------------------------------- armor, belt, sword

def half_shell(name, center, radii, mat, keep, thickness=0.012):
    """An ellipsoid cut to the vertices where keep(p) holds, thickened outward-in."""
    o = ellipsoid(name, center, radii, mat, 24, 14)
    bm = bmesh.new()
    bm.from_mesh(o.data)
    bmesh.ops.delete(bm, geom=[v for v in bm.verts if not keep(v.co - Vector(center))], context="VERTS")
    bm.to_mesh(o.data)
    bm.free()
    sol = o.modifiers.new("Solidify", "SOLIDIFY")
    sol.thickness = thickness
    dgx = bpy.context.evaluated_depsgraph_get()
    me2 = bpy.data.meshes.new_from_object(o.evaluated_get(dgx))
    o.modifiers.clear()
    o.data = me2
    for p in o.data.polygons:
        p.use_smooth = True
    return o


def plate_from_body(name, keep, lift, thickness, mat):
    """Armor that fits: the body faces where keep(centre, normal) holds, lifted off the skin and thickened."""
    bm = bmesh.new()
    bm.from_mesh(body.data)
    drop = [f for f in bm.faces if not keep(f.calc_center_median(), f.normal)]
    bmesh.ops.delete(bm, geom=drop, context="FACES")
    bmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context="VERTS")
    bm.normal_update()
    for v in bm.verts:
        v.co += v.normal * lift
    me = bpy.data.meshes.new(name)
    bm.to_mesh(me)
    bm.free()
    o = link(bpy.data.objects.new(name, me))
    o.data.materials.append(MAT[mat])
    for p in me.polygons:
        p.material_index = 0
        p.use_smooth = True
    sol = o.modifiers.new("Solidify", "SOLIDIFY")
    sol.thickness = thickness
    sol.offset = 1.0
    return o


