# ---------------------------------------------------------------- bind: body weights from the skeleton, parts rigid

def select_only(objs, active):
    for o in scene.objects:
        o.select_set(False)
    for o in objs:
        o.select_set(True)
    bpy.context.view_layer.objects.active = active


select_only([body, rig], rig)
with bpy.context.temp_override(active_object=rig, object=rig, selected_objects=[body, rig], selected_editable_objects=[body, rig]):
    bpy.ops.object.parent_set(type="ARMATURE_AUTO")
unweighted = sum(1 for v in body.data.vertices if not any(g.weight > 0.001 for g in v.groups))
print("[otherworlder] body verts", len(body.data.vertices), "unweighted", unweighted)

for obj, bone in parts:
    vg = obj.vertex_groups.new(name=bone)
    vg.add(range(len(obj.data.vertices)), 1.0, "REPLACE")
    if obj.modifiers:
        dgx = bpy.context.evaluated_depsgraph_get()
        me2 = bpy.data.meshes.new_from_object(obj.evaluated_get(dgx))
        obj.modifiers.clear()
        obj.data = me2
        obj.vertex_groups.clear()
        vg = obj.vertex_groups.new(name=bone)
        vg.add(range(len(obj.data.vertices)), 1.0, "REPLACE")

others = [o for o, _ in parts]
select_only([body] + others, body)
with bpy.context.temp_override(active_object=body, object=body, selected_objects=[body] + others, selected_editable_objects=[body] + others):
    bpy.ops.object.join()
body.name = "OtherworlderMesh"

select_only(sword_parts, sword_parts[0])
