# ---------------------------------------------------------------- posing helpers

PB = rig.pose.bones
for pb in PB:
    pb.rotation_mode = "QUATERNION"


def update():
    bpy.context.view_layer.update()


def reset():
    for pb in PB:
        pb.rotation_quaternion = Quaternion()
        pb.location = Vector()
        pb.scale = Vector((1, 1, 1))
    update()


def local_rot(name, yaw=0.0, pitch=0.0, roll=0.0):
    """Rotation in the bone's own frame: pitch = bend forward (+), yaw = turn left (+), roll = tip sideways."""
    q = (Quaternion((0, 1, 0), math.radians(yaw)) @ Quaternion((1, 0, 0), math.radians(pitch))
         @ Quaternion((0, 0, 1), math.radians(roll)))
    PB[name].rotation_quaternion = q


def aim(name, direction, hint):
    """Point the bone's Y along direction; its Z as close to hint as possible. Armature space."""
    y = n(direction)
    h = Vector(hint)
    if abs(n(h).dot(y)) > 0.97:
        h = U if abs(y.dot(U)) < 0.9 else F
    z = n(h - y * h.dot(y))
    x = y.cross(z)
    rot = Matrix((x, y, z)).transposed()
    head = PB[name].matrix.translation.copy()
    PB[name].matrix = Matrix.Translation(head) @ rot.to_4x4()
    update()


def two_bone(upper, lower, target, pole):
    """Point upper and lower so lower's tail reaches target, bending toward pole."""
    root = PB[upper].matrix.translation.copy()
    a, b = LEN[upper], LEN[lower]
    to = Vector(target) - root
    d = max(abs(a - b) + 1e-3, min(a + b - 1e-3, to.length))
    nd = n(to)
    cos_a = (a * a + d * d - b * b) / (2 * a * d)
    sin_a = math.sqrt(max(0.0, 1 - cos_a * cos_a))
    p = Vector(pole)
    perp = p - nd * p.dot(nd)
    perp = n(perp) if perp.length > 1e-4 else n(nd.cross(LEFT))
    up_dir = nd * cos_a + perp * sin_a
    knee = root + up_dir * a
    low_dir = n(root + nd * d - knee)
    aim(upper, up_dir, low_dir)
    aim(lower, low_dir, perp)


def leg(side, ankle, foot_pitch=0.0, knee_out=0.15):
    sx = 1 if side == "Left" else -1
    two_bone(side + "UpperLeg", side + "LowerLeg", ankle, n(F + LEFT * sx * knee_out))
    fdir = n(Vector((0, -0.13, -0.065)))
    fdir = Quaternion(LEFT, math.radians(foot_pitch)) @ fdir
    aim(side + "Foot", fdir, U)
    aim(side + "Toes", n(Vector((0, -1, -0.05))), U)


def arm(side, wrist, hand_dir, twist_hint, elbow_pole):
    two_bone(side + "UpperArm", side + "LowerArm", wrist, elbow_pole)
    aim(side + "Hand", hand_dir, twist_hint)


STAND = {"Left": Vector((0.12, -0.03, 0.09)), "Right": Vector((-0.12, 0.05, 0.09))}


def apply_pose(p):
    """p: hips (off, yaw, pitch, roll), spine/chest/neck/head (yaw, pitch, roll), feet, hands."""
    reset()
    off, (hy, hp, hr) = p.get("hips", ((0, 0, 0), (0, 0, 0)))
    PB["Hips"].location = Vector((off[0], off[2], -off[1]))  # bone frame: X left, Y up, Z forward
    local_rot("Hips", hy, hp, hr)
    for bone in ("Spine", "Chest", "Neck", "Head"):
        local_rot(bone, *p.get(bone.lower(), (0, 0, 0)))
    for side in ("Left", "Right"):
        local_rot(side + "Shoulder", *p.get(side.lower() + "_shoulder", (0, 0, 0)))
    update()
    for side in ("Left", "Right"):
        fp = p.get(side.lower() + "_foot", (STAND[side], 0.0))
        leg(side, fp[0], fp[1])
    for side in ("Left", "Right"):
        h = p[side.lower() + "_hand"]
        arm(side, h[0], h[1], h[2], h[3])


LAST_Q = {}


def key(frame, with_location=("Hips",)):
    for pb in PB:
        # Keys are interpolated per component: keep each quaternion on the same side as the last one,
        # or a turn past 180 degrees (the roll) would spin back the long way.
        q = pb.rotation_quaternion.copy()
        if pb.name in LAST_Q:
            q.make_compatible(LAST_Q[pb.name])
            pb.rotation_quaternion = q
        LAST_Q[pb.name] = q
        pb.keyframe_insert("rotation_quaternion", frame=frame)
        if pb.name in with_location:
            pb.keyframe_insert("location", frame=frame)


ACTIONS = []


def new_action(name):
    act = bpy.data.actions.new(name)
    act.use_fake_user = True
    rig.animation_data_create()
    rig.animation_data.action = act
    ACTIONS.append(act)
    LAST_Q.clear()
    return act


def keyed_action(name, frames):
    """frames: list of (frame, pose dict)."""
    new_action(name)
    for f, pose in frames:
        apply_pose(pose)
        key(f)
    return name


def lerp(a, b, t):
    return a + (b - a) * t


# ---------------------------------------------------------------- poses

def grip(blade, knuckles):
    """The hand's pointing direction for a blade along `blade`: at right angles to it (the blade leaves the fist
    sideways), as close to `knuckles` as possible."""
    b = n(blade)
    k = Vector(knuckles)
    h = k - b * k.dot(b)
    if h.length < 1e-3:
        h = D - b * D.dot(b)
    return n(h)


def sword(wrist, blade, knuckles, elbow):
    return (Vector(wrist), grip(blade, knuckles), n(blade), n(elbow))


ELBOW_R = n(B * 0.6 + D * 0.4 + RIGHT * 0.7)   # the sword arm's elbow points out and back
ELBOW_L = n(B + D * 0.5 + LEFT * 0.4)
GUARD_BLADE = n(F * 0.8 + U * 0.35 + LEFT * 0.25)


def left_hand(wrist, point=None):
    return (Vector(wrist), n(point if point is not None else D + F * 0.25), F, ELBOW_L)


def guard(breath=0.0):
    """Ready stance: sword low in front, tip forward and up toward the enemy."""
    return {
        "hips": ((0, 0, -0.035 - 0.008 * breath), (-8, 0, 0)),
        "spine": (0, 3, 0), "chest": (8, 2 + 2 * breath, 0), "neck": (0, 0, 0), "head": (2, -4, 0),
        "left_foot": (Vector((0.13, -0.07, 0.09)), 0.0),
        "right_foot": (Vector((-0.12, 0.13, 0.09)), 0.0),
        "right_hand": sword((-0.21, -0.30, 1.03 - 0.01 * breath), GUARD_BLADE, D + F * 0.2, ELBOW_R),
        "left_hand": left_hand((0.25, -0.07, 0.94 - 0.01 * breath)),
    }


def with_(base, **changes):
    p = dict(base)
    p.update(changes)
    return p


def recover():
    """Bringing the sword back up in front before settling into the guard (so it doesn't sweep back through the swing)."""
    return with_(guard(), right_hand=sword((-0.08, -0.36, 1.12), n(F * 0.8 + U * 0.45), D + F * 0.2, ELBOW_R))


