# ---------------------------------------------------------------- locomotion: a gait with planted feet

def smooth(t):
    return t * t * (3 - 2 * t)


def gait(name, move, speed, cycle, duty, lift, bob, lean, arm_swing, sword_swing, cross=0.0):
    """move: unit direction the body travels (in the character's frame); feet stay planted while on the ground."""
    new_action(name)
    frames = max(8, int(round(cycle * FPS / 2)) * 2)  # even, so keys every 2 frames land on the loop's end
    move = Vector(move)
    stance_len = speed * cycle * duty
    forwardish = abs(move.y) > 0.5
    for f in range(0, frames + 1, 2):
        t = (f % frames) / frames
        feet, pitch = {}, {}
        for foot, phase0 in (("Left", 0.0), ("Right", 0.5)):
            q = (t + phase0) % 1.0
            if q < duty:                              # planted: slides back under the body
                along = lerp(stance_len / 2, -stance_len / 2, q / duty)
                h, fp = 0.0, 0.0
            else:                                     # swinging forward through the air
                s = (q - duty) / (1 - duty)
                along = lerp(-stance_len / 2, stance_len / 2, smooth(s))
                h = lift * math.sin(math.pi * s)
                fp = 30.0 * math.sin(math.pi * s) * (1 if forwardish else 0.4)
            base = Vector((0.11 if foot == "Left" else -0.11, 0.0, 0.09))
            if cross:
                base += F * (cross if foot == "Left" else -cross)
            feet[foot] = base + move * along + U * h
            pitch[foot] = fp
        # Hips: lowest just after each contact, sway over the planted foot, turn with the stride; shoulders counter-turn.
        bob_z = -0.035 - bob * (0.5 + 0.5 * math.cos(4 * math.pi * (t - 0.05)))
        sway = 0.025 * math.sin(2 * math.pi * t) * (1 if forwardish else 0.4)
        twist = 9 * math.sin(2 * math.pi * t) * (1 if forwardish else 0.3)
        lean_v = move * lean
        swing = math.sin(2 * math.pi * t)
        lh = Vector((0.24, -0.04, 0.95)) + move * (-arm_swing * swing) + F * 0.03 + U * 0.05 * abs(swing)
        rh = Vector((-0.22, -0.28, 1.05)) + move * (sword_swing * swing) + U * 0.02 * abs(swing)
        pose = {
            "hips": ((sway, 0, bob_z), (twist, -lean_v.y * 60, lean_v.x * 40)),
            "spine": (-twist * 0.5, 2, 0), "chest": (-twist * 0.9, 2, 0), "neck": (0, 0, 0), "head": (twist * 0.4, -2, 0),
            "left_foot": (feet["Left"], pitch["Left"]), "right_foot": (feet["Right"], pitch["Right"]),
            "left_hand": left_hand(lh, D + F * 0.3),
            "right_hand": sword(rh, GUARD_BLADE, D + F * 0.2, ELBOW_R),
        }
        apply_pose(pose)
        key(f)
    return name


