def apply_roll(turn, drop):
    """A tucked forward roll: the hips turn `turn` degrees forward and drop by `drop`; knees and hands stay tucked."""
    reset()
    PB["Hips"].location = Vector((0, -drop, 0))
    local_rot("Hips", 0, turn, 0)
    for bone, deg in (("Spine", 25), ("Chest", 25), ("Neck", 20), ("Head", 15)):
        local_rot(bone, 0, deg, 0)
    update()
    hips = PB["Hips"].matrix
    rot = hips.to_3x3()
    for side, sx in (("Left", 1), ("Right", -1)):
        two_bone(side + "UpperLeg", side + "LowerLeg", hips @ Vector((0.10 * sx, -0.32, 0.22)), (rot @ Vector((0, 0, 1))).normalized())
        aim(side + "Foot", rot @ Vector((0, -0.4, 1)), rot @ Vector((0, 1, 0)))
        aim(side + "Toes", rot @ Vector((0, -0.2, 1)), rot @ Vector((0, 1, 0)))
        two_bone(side + "UpperArm", side + "LowerArm", hips @ Vector((0.16 * sx, -0.02, 0.30)), rot @ Vector((0.6 * sx, 0.3, -0.6)))
        aim(side + "Hand", rot @ Vector((0, -0.3, 1)), rot @ Vector((0, 1, 0)))


new_action("Roll")
for f, turn, drop in ((0, 15, 0.20), (2, 50, 0.40), (4, 100, 0.52), (6, 160, 0.56), (8, 220, 0.55), (10, 280, 0.46),
                      (12, 330, 0.30)):
    apply_roll(turn, drop)
    key(f)
