    scene.display.shading.show_shadows = True
    scene.render.resolution_x = 420
    scene.render.resolution_y = 520
    scene.render.film_transparent = False
    world = bpy.data.worlds.new("W")
    scene.world = world
    world.color = (0.55, 0.62, 0.70)
    cam_data = bpy.data.cameras.new("Cam")
    cam_data.lens = 50
    cam = link(bpy.data.objects.new("Cam", cam_data))
    scene.camera = cam
    ground = mesh_object("Ground", [(-2, -2, 0), (2, -2, 0), (2, 2, 0), (-2, 2, 0)], [(0, 1, 2, 3)], "Cloth")

    def shoot(path, yaw_deg, dist=4.2, height=1.0, look_z=0.95):
        a = math.radians(yaw_deg)
        pos = Vector((math.sin(a) * dist, -math.cos(a) * dist, height))
        cam.location = pos
        look = Vector((0, 0, look_z)) - pos
        cam.rotation_euler = look.to_track_quat("-Z", "Y").to_euler()
        scene.render.filepath = path
        bpy.ops.render.render(write_still=True)

    rig.animation_data.action = None
    reset()
    for label, yaw in (("front", 0), ("side", 90), ("back", 180), ("three_quarter", 35)):
        shoot(os.path.join(RENDERS, "rest_" + label + ".png"), yaw)
    shoot(os.path.join(RENDERS, "face.png"), 0, dist=1.1, height=1.66, look_z=1.64)
    for act in ACTIONS:
        rig.animation_data.action = act
        start, end = (int(x) for x in act.frame_range)
        count = 6 if end - start > 10 else 4
        for i in range(count):
            fr = start + round((end - start) * i / (count - 1)) if count > 1 else start
            scene.frame_set(fr)
            shoot(os.path.join(RENDERS, "%s_%02d.png" % (act.name, fr)), 35)
    print("[otherworlder] renders in", RENDERS)
